    return {"n":n,"title":title,"url":f"https://doi.org/{doi}" if doi else f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/","publisher":pub+(f", {pmc}" if pmc else "")+f", PubMed {pmid}","accessed":A}
